/* LingoQuest AR — static demo, no account/server/API; progress saved only in this browser. */
(() => {
  'use strict';
  const {stages,lessons,placement,alphabet,foundations,alphabetNotes,pronunciation,phonics} = window.LQ_CONTENT;
  const {stories,dialogs,patterns} = window.LQ_ADVENTURE;
  const KEY = 'lingoquest_ar_v1';
  const appEl = document.getElementById('app');
  const toastEl = document.getElementById('toast');
  const skills = {alphabet:'الحروف',vocab:'المفردات',grammar:'القواعد',listening:'الاستماع',reading:'القراءة',writing:'الكتابة'};
  const pages = [{id:'home',label:'الرئيسية',emoji:'🏡'},{id:'path',label:'مساري',emoji:'🗺️'},{id:'games',label:'ساحة الألعاب',emoji:'🎮'},{id:'adventure',label:'مغامرات V4',emoji:'📖'},{id:'achievements',label:'إنجازاتي',emoji:'🏆'},{id:'settings',label:'حسابي',emoji:'⚙️'}];
  let data;
  try { const v = JSON.parse(localStorage.getItem(KEY) || '{}');data={profiles:Array.isArray(v.profiles)?v.profiles:[]}; } catch {data={profiles:[]};}
  let profile=null,page='home',quiz=null,placementSession=null,result=null,modal=null,pronounceIndex=0,pronounceText='',micStatus='',activeLessonId=null,openedCards=new Set(),foundationPageId=null;
  let phonicsPageId=null,adventureTab='stories',storyId=null,patternId=null,dialogId=null,dialogTurn=0,dialogCorrect=0,dialogAnswered=null,dialogLog=[],showTranslation=true;
  let toastTimer=null;
  const E = value => String(value==null?'':value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const idx = id => stages.findIndex(s=>s.id===id);
  const stageOf = id => stages.find(s=>s.id===id) || stages[0];
  const english = value => `<span class="en" lang="en">${E(value)}</span>`;
  const today = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  const now = () => new Date().toISOString();
  const pct = (n,d) => d?Math.round(n*100/d):0;
  const norm = v => String(v||'').toLowerCase().normalize('NFKC').replace(/[‘’']/g,'').replace(/[.,!?]/g,'').replace(/\s+/g,' ').trim();
  const shuffled = arr => {const a=[...arr];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
  const safeProfile = p => ({id:p.id,name:p.name,createdAt:p.createdAt||now(),stage:p.stage||null,placementDone:!!p.placementDone,placementResult:p.placementResult||null,xp:p.xp||0,streak:p.streak||0,lastActive:p.lastActive||'',completed:p.completed||{},gatePass:p.gatePass||{},attempts:p.attempts||0,skillStats:p.skillStats||{},mistakes:p.mistakes||[],history:p.history||[],practiceCount:p.practiceCount||0,foundations:p.foundations&&typeof p.foundations==='object'?p.foundations:{},phonics:p.phonics&&typeof p.phonics==='object'?p.phonics:{},stories:p.stories&&typeof p.stories==='object'?p.stories:{},dialogues:p.dialogues&&typeof p.dialogues==='object'?p.dialogues:{},readingPatterns:p.readingPatterns&&typeof p.readingPatterns==='object'?p.readingPatterns:{},reviewCards:p.reviewCards&&typeof p.reviewCards==='object'?p.reviewCards:{},daily:p.daily&&typeof p.daily==='object'?p.daily:{date:'',correct:0,total:0,bonusClaimed:false}});
  data.profiles=data.profiles.map(safeProfile);
  // Migrate V2 error bank into review scheduler without losing any existing progress.
  for(const p of data.profiles){
    for(const m of p.mistakes){if(m?.uid && m.item && !p.reviewCards[m.uid])p.reviewCards[m.uid]={item:m.item,dueAt:0,step:0,lapses:1};}
  }
  function store(){try{localStorage.setItem(KEY,JSON.stringify(data));}catch{toast('تعذّر الحفظ في هذا المتصفح. تأكد من السماح بالتخزين المحلي.');}}
  function pop(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),3400);}
  const toast = pop;
  function activate(p){profile=p;page=p.placementDone?'home':'intro';quiz=null;placementSession=null;result=null;modal=null;activeLessonId=null;openedCards.clear();foundationPageId=null;phonicsPageId=null;storyId=null;dialogId=null;patternId=null;dialogTurn=0;dialogLog=[];render();}
  function activeStage(){return stageOf(profile?.stage);}
  function foundationFinished(){return foundations.every(g=>!!profile.foundations[g.id]) || !!profile.completed['a0-1'] || idx(profile.stage)>0;}
  function foundationGroupAvailable(group){const i=foundations.findIndex(g=>g.id===group.id);return i===0 || !!profile.foundations[foundations[i-1].id] || foundationFinished();}
  function foundationNext(){return foundations.find(g=>!profile.foundations[g.id]) || foundations[0];}
  function foundationCount(){return foundations.filter(g=>!!profile.foundations[g.id]).length;}
  function phonicsFinished(){return phonics.every(g=>!!profile.phonics[g.id]) || !!profile.completed['a0-1'] || idx(profile.stage)>0;}
  function phonicsCount(){return phonics.filter(g=>!!profile.phonics[g.id]).length;}
  function phonicsAvailable(g){if(profile.stage==='A0'&&!foundationFinished())return false;const j=phonics.findIndex(x=>x.id===g.id);return j===0||!!profile.phonics[phonics[j-1].id]||phonicsFinished();}
  function dueReviews(){return Object.entries(profile.reviewCards).filter(([,v])=>v&&v.item&&Number(v.dueAt||0)<=Date.now());}
  function scheduledReviews(){return Object.values(profile.reviewCards).filter(v=>v?.item).length;}
  function dailyInfo(){return profile.daily?.date===today()?profile.daily:{date:today(),correct:0,total:0,bonusClaimed:false};}
  function reviewProgress(row,correct){
    const old=profile.reviewCards[row.uid];
    if(correct&&!old)return;
    const step=correct?Math.min((old?.step||0)+1,6):0;
    const intervals=[0,1,3,7,14,30,60];
    profile.reviewCards[row.uid]={item:row.item,step,lapses:(old?.lapses||0)+(correct?0:1),dueAt:Date.now()+intervals[step]*86400000};
  }
  function stepUnlocked(lesson){
    if(lesson.id==='a0-1'&&(!foundationFinished()||!phonicsFinished()))return false;
const s=idx(lesson.stage),my=idx(profile.stage);if(s>my)return false;const ls=lessons.filter(l=>l.stage===lesson.stage);const k=ls.findIndex(l=>l.id===lesson.id);return k===0||!!profile.completed[ls[k-1].id];}
  function stageLessons(s){return lessons.filter(l=>l.stage===s);}
  function gateUnlocked(s){return stageLessons(s).every(l=>!!profile.completed[l.id]) && idx(s)<=idx(profile.stage);}
  function getNextLesson(){return lessons.find(l=>l.stage===profile.stage&&stepUnlocked(l)&&!profile.completed[l.id]);}
  function touchActivity(){const d=today();if(profile.lastActive!==d){let yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);const y=`${yesterday.getFullYear()}-${String(yesterday.getMonth()+1).padStart(2,'0')}-${String(yesterday.getDate()).padStart(2,'0')}`;profile.streak=profile.lastActive===y?profile.streak+1:1;profile.lastActive=d;}}
  function addStats(skill,correct){const key=skill||'vocab';if(!profile.skillStats[key])profile.skillStats[key]={right:0,total:0};profile.skillStats[key].total++;if(correct)profile.skillStats[key].right++;}
  function weakSkill(){const rows=Object.entries(profile.skillStats).filter(([,v])=>v.total>=2).sort((a,b)=>a[1].right/a[1].total-b[1].right/b[1].total);return rows.length?rows[0][0]:null;}
  function pronounce(text){if(!('speechSynthesis' in window)){toast('جهازك لا يدعم النطق الآلي هنا.');return;}try{window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.82;u.pitch=1.06;const voices=window.speechSynthesis.getVoices();const voice=voices.find(v=>v.lang.toLowerCase().startsWith('en')&&v.localService)||voices.find(v=>v.lang.toLowerCase().startsWith('en'));if(voice)u.voice=voice;window.speechSynthesis.speak(u);}catch{toast('تعذّر تشغيل الصوت. جرّب متصفحًا آخر.');}}
  function nav(to){if(quiz||placementSession){modal={kind:'exit',to};render();return;}result=null;page=to;render();}
  function boxBadge(t){return `<span class="chip">${E(t)}</span>`;}
  function progressBar(p){return `<div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p}"><div class="progress-fill" style="width:${p}%"></div></div>`;}
  function renderWelcome(){const profiles=data.profiles.map(p=>`<button class="profile-option" data-action="choose-profile" data-id="${E(p.id)}"><span class="flex"><span class="avatar">🧑‍🚀</span><span><strong>${E(p.name)}</strong><br><small class="muted">${p.placementDone?`المستوى ${E(p.stage)}`:'بانتظار اختبار المستوى'}</small></span></span><span>←</span></button>`).join('');return `<div class="welcome"><div class="w-header"><div class="logo"><span class="logo-mark">L</span> مغامرة إنجليش <small style="font-size:12px;opacity:.65">BETA</small></div>${boxBadge('🎯 تعلّم حسب مستواك')}</div><div class="w-body"><section><div class="eyebrow" style="color:#bdb4ff">LEARN • PLAY • LEVEL UP</div><h1>من أول حرف…<br>إلى <span class="highlight">ثقة الحديث</span> ✨</h1><p class="desc">مغامرة لتعلّم الإنجليزية تبدأ باختبار مستواك، ثم تصنع لك طريقًا خاصًا مليئًا بالتحديات والألعاب والكلمات والنجوم. تعلّم بخطوات صغيرة، وتقدّم عندما تتقن.</p><div class="w-features"><span>🧠 اختبار ذكي مبدئي</span><span>🗺️ مسار شخصي</span><span>🎧 صوت وتدريب</span><span>🏆 مكافآت حقيقية داخل اللعبة</span></div><div class="flex wrap"><span class="chip" style="background:#ffffff19;color:#fff">6 مستويات تدريبية</span><span class="chip" style="background:#ffffff19;color:#fff">12 درسًا تجريبيًا</span><span class="chip" style="background:#ffffff19;color:#fff">ألعاب الأصوات + المراجعة</span></div></section><section class="welcome-card"><div class="hero-graphic"><span class="graphic-stars">✦ ✨</span><span class="mascot">🦊</span><span class="graphic-stars">⭐</span></div><div class="center"><h2 style="margin:0 0 6px">جاهز تبدأ مغامرتك؟</h2><p class="muted small" style="margin:0 0 20px">أدخل اسم المتعلم لبدء اختبار المستوى المجاني</p></div><form class="welcome-form" data-form="create"><label class="small strong" for="student-name">اسم المتعلم</label><input id="student-name" name="name" class="input" maxlength="30" placeholder="مثال: هتان" autocomplete="off" required><button class="btn btn-primary wide" type="submit">ابدأ مغامرتي <span>🚀</span></button></form>${profiles?`<div class="divider"></div><p class="mini-title">أكمل مغامرة سابقة</p><div class="profiles">${profiles}</div>`:''}<div class="divider"></div><button type="button" class="btn btn-outline wide" data-action="pick-import">📂 استيراد ملف تقدم سابق V2 / V3 / V4</button><input type="file" id="import-file" accept=".json,application/json" hidden><p class="footnote">بيانات النسخة التجريبية تُحفظ في هذا المتصفح فقط. يمكنك نقلها بين الملفات باستخدام تصدير ثم استيراد JSON، دون خادم.</p></section></div></div>`;}
  function renderShell(inner){const st=activeStage();const navButtons=pages.map(x=>`<button class="nav-button ${page===x.id?'active':''}" data-action="nav" data-page="${x.id}"><span class="nav-emoji">${x.emoji}</span>${x.label}</button>`).join('');const mob=pages.slice(0,4).map(x=>`<button class="mobile-item ${page===x.id?'active':''}" data-action="nav" data-page="${x.id}"><span>${x.emoji}</span>${x.label}</button>`).join('');return `<div class="shell"><aside class="sidebar"><div class="logo"><span class="logo-mark">L</span> مغامرة إنجليش</div><div class="side-profile flex"><span class="avatar">🧑‍🚀</span><div><strong>${E(profile.name)}</strong><br><small>${E(st.name)} • ${E(st.id)}</small></div></div><nav class="nav" aria-label="التنقل">${navButtons}</nav><div class="side-bottom"><div class="tip">🌟 <strong>تذكّر:</strong> كل محاولة فرصة لتعلّم شيء جديد.</div><button class="nav-button" data-action="switch-profile">🔄 تبديل المتعلم</button></div></aside><div class="main-wrap"><header class="topbar"><div><div class="tiny muted">رحلة اللغة الإنجليزية</div><div class="title-line">${page==='intro'?'لنكتشف مستواك':page==='placement'?'اختبار تحديد المستوى':quiz?'تحدٍ جديد':page==='result'?'نتيجة التحدّي':page==='lessonPreview'?'بطاقات التعلّم':page==='foundations'?'أكاديمية الحروف':page==='foundationLesson'?'درس الحروف':page==='phonics'?'مختبر الأصوات':page==='phonicLesson'?'دمج الأصوات':pages.find(x=>x.id===page)?.label||'أهلًا بك'} 👋</div></div><div class="flex wrap"><span class="stat-pill">🔥 ${profile.streak} يوم</span><span class="stat-pill">⭐ ${profile.xp} XP</span><span class="stat-pill">${E(st.id)} ${st.emoji}</span></div></header><main class="main">${inner}<div class="footnote">مغامرة إنجليش — إصدار تجريبي تعليمي، ليس اختبار CEFR معتمدًا. التقدّم محفوظ على الجهاز الحالي.</div></main></div><nav class="mobile-nav" aria-label="التنقل السريع">${mob}<button class="mobile-item ${page==='settings'?'active':''}" data-action="nav" data-page="settings"><span>⚙️</span>حسابي</button></nav></div>${modal?renderModal():''}`;}
  function renderIntro(){return `<div class="result-card"><div class="result-emoji">🔍</div><div class="eyebrow">THE PLACEMENT CHALLENGE</div><h2 class="result-title">أهلًا ${E(profile.name)}! 👋</h2><p class="result-summary">سنطرح عليك <strong>24 سؤالًا</strong> تزداد صعوبتها تدريجيًا، تشمل المفردات والقواعد والاستماع والقراءة. نستخدم إجاباتك لوضعك في <strong>نقطة انطلاق تقديرية</strong> بين مستويات A0 وC1.</p><div class="grid-3" style="margin:22px 0"><div class="tip">📝 24 سؤالًا</div><div class="tip">🎧 استماع</div><div class="tip">🗺️ طريق شخصي</div></div><div class="tip" style="margin-bottom:19px">لا تقلق إذا لم تعرف الإجابة؛ اختر ما تظنه صحيحًا. هذا تقييم داخل اللعبة وليس شهادة رسمية.</div><button class="btn btn-primary wide" data-action="start-placement">ابدأ اختبار المستوى 🚀</button><button class="btn btn-ghost wide" data-action="switch-profile" style="margin-top:10px">تبديل المتعلم</button></div>`;}
  function renderLessonPreview(){
    const l=lessons.find(x=>x.id===activeLessonId);
    if(!l)return `<div class="card"><h2>تعذّر فتح الدرس</h2><button class="btn btn-outline" data-action="go-path">العودة للمسار</button></div>`;
    const stage=stageOf(l.stage);
    const cards=l.cards.map(([word,meaning],i)=>{
      const opened=openedCards.has(i);
      return `<article class="flash-card"><div class="flex between"><span class="chip">البطاقة ${i+1} / ${l.cards.length}</span><span aria-hidden="true">${opened?'✅':'✨'}</span></div><div class="flash-word" lang="en" dir="ltr">${E(word)}</div><div class="flash-meaning">${opened?E(meaning):'اضغط «اكشف المعنى» لتتعلم هذه الكلمة'}</div><div class="flex wrap" style="justify-content:center"><button class="btn btn-outline btn-sm" data-action="flip-card" data-i="${i}">${opened?'أخفِ المعنى 🙈':'اكشف المعنى 👀'}</button><button class="btn btn-mint btn-sm" data-action="say" data-say="${E(word)}">🔊 اسمعها</button></div></article>`;
    }).join('');
    return `<div class="road-head"><div><span class="eyebrow">LEARN FIRST • THEN PLAY</span><h2 class="section-title">${l.icon} ${E(l.title)}</h2><p class="muted small no-margin">${E(stage.id)} • ${E(stage.name)} • نحو ${l.time} دقائق</p></div><button class="btn btn-outline btn-sm" data-action="go-path">العودة للمسار →</button></div><section class="card"><h3 class="mini-title">🎯 ما الذي ستتعلمه؟</h3><p class="no-margin" style="line-height:2">${E(l.goal)}</p><div class="tip" style="margin-top:14px">اقرأ الكلمات، اكشف المعاني، اضغط للاستماع وكرّر النطق، ثم ابدأ ألعاب الدرس. اجتز التحدّي بنسبة 80% أو أكثر لفتح الدرس التالي.</div></section><div class="flash-grid">${cards}</div><section class="card center" style="margin-top:18px"><h3 class="mini-title">🚀 جاهز لتحدّي الدرس؟</h3><p class="small muted">ستجد أسئلة اختيار واستماع وتوصيل وترتيب وكتابة بحسب هذا الدرس.</p><button class="btn btn-primary" data-action="begin-lesson" data-id="${E(l.id)}">ابدأ ألعاب الدرس الآن ←</button></section>`;
  }
  function renderPlacement(){const n=placementSession.index,item=placement[n];return `<div class="quiz-frame"><div class="quiz-head"><span class="quiz-counter">اختبار تحديد المستوى • السؤال ${n+1} من ${placement.length}</span><span class="chip">${E(skills[item.skill]||'لغة')}</span></div>${progressBar(pct(n,placement.length))}<div class="quiz-card" style="margin-top:18px"><p class="q-heading">🔎 اختر إجابة واحدة</p><h2 class="q-text">${E(item.q)}</h2>${item.type==='listen'?`<button class="sound-btn" data-action="say" data-say="${E(item.say)}">🔊 اضغط للاستماع</button><p class="small muted">يمكن إعادة تشغيل المقطع قبل الإجابة.</p>`:''}<div class="options">${item.options.map((opt,i)=>`<button class="option" data-action="placement-answer" data-i="${i}">${english(opt)}</button>`).join('')}</div><div class="test-info" style="margin-top:19px">لن نخبرك بصحة الإجابة أثناء الاختبار حتى تكون النتيجة أقرب لمستواك الفعلي.</div></div></div>`;}
  function skillSummaryRows(resultStats){return Object.entries(skills).map(([id,name])=>{const s=resultStats[id]||{right:0,total:0};if(!s.total)return '';return `<div><div class="skill-row"><span>${name}</span><span>${s.right}/${s.total} • ${pct(s.right,s.total)}%</span></div>${progressBar(pct(s.right,s.total))}</div>`;}).join('');}
  function renderPlacementResult(){const r=profile.placementResult,st=activeStage();return `<div class="result-card"><div class="result-emoji">${st.emoji}</div><span class="chip">نتيجة تحديد المستوى</span><h2 class="result-title">انطلاقتك من ${E(st.id)}: ${E(st.name)}</h2><p class="result-summary">${E(profile.name)}، هذا هو المستوى المقترح لك بناءً على الاختبار التشخيصي. مسارك الشخصي جاهز الآن!</p><div class="grid-3" style="margin:18px 0 22px"><div class="tip"><strong>مبتدئ</strong><br>${r.sections.A0}/8</div><div class="tip"><strong>متوسط</strong><br>${r.sections.B1}/8</div><div class="tip"><strong>متقدم</strong><br>${r.sections.C1}/8</div></div><div class="card" style="text-align:right;box-shadow:none"><h3 class="mini-title">مهاراتك في الاختبار</h3><div class="skill-bars">${skillSummaryRows(r.stats)}</div></div><div class="tip" style="margin:18px 0">التصنيف تقديري بناءً على 24 سؤالًا فقط؛ ليس قياس CEFR معياريًا، ويمكنك مراجعة أي مستوى أدنى من مستواك المقترح.</div><button class="btn btn-primary wide" data-action="go-path">افتح مساري التعليمي 🗺️</button></div>`;}
  function nextPanel(){if(profile.stage==='A0'&&!foundationFinished())return {label:'ابدأ حروفك الأولى (A–Z)',action:'open-foundations',id:'',icon:'🔤'};if(profile.stage==='A0'&&!phonicsFinished())return {label:'ادمج الأصوات وركّب أول كلماتك',action:'open-phonics',id:'',icon:'🧩'};const next=getNextLesson(),s=activeStage();if(next)return {label:'أكمل الدرس: '+next.title,action:'start-lesson',id:next.id,icon:next.icon};if(gateUnlocked(profile.stage)&&!profile.gatePass[profile.stage])return{label:`تحدّي ترقية ${s.id}`,action:'start-gate',id:s.id,icon:'🏆'};if(profile.gatePass.C1)return{label:'أحسنت! راجع مهاراتك في الألعاب',action:'nav',id:'games',icon:'👑'};return{label:'تفقّد مسارك',action:'nav',id:'path',icon:'🗺️'};}
  function renderFoundationHome(){return `<div class="foundation-inline"><div class="flex between wrap"><div><strong>🔤 أكاديمية الحروف</strong><div class="small muted">${foundationCount()} / 4 مجموعات مكتملة</div></div><button class="btn btn-outline btn-sm" data-action="open-foundations">${foundationFinished()?'مراجعة الحروف':'ابدأ الحروف'}</button></div>${progressBar(pct(foundationCount(),4))}</div>`;}
  function renderHome(){const st=activeStage(),next=nextPanel(),finished=stageLessons(st.id).filter(l=>profile.completed[l.id]).length,weak=weakSkill();return `<div class="dash-hero"><div style="z-index:1"><span class="chip" style="background:#ffffff25;color:#fff">مستواك الحالي ${E(st.id)} • ${E(st.group)}</span><h2>يا ${E(profile.name)}، كل كلمة جديدة تقرّبك من هدفك ✨</h2><p>${E(st.subtitle)} — لنكمل المغامرة معًا.</p><button class="btn btn-white" data-action="${next.action}" ${next.action==='nav'?`data-page="${next.id}"`:`data-id="${E(next.id)}"`}>${E(next.label)} <span>←</span></button></div><div class="hero-emoji">${st.emoji}</div></div><div class="metric-grid"><div class="metric"><span class="metric-icon">⭐</span><div><strong>${profile.xp}</strong><small class="muted">نقاط الخبرة</small></div></div><div class="metric"><span class="metric-icon">✅</span><div><strong>${Object.keys(profile.completed).length}</strong><small class="muted">دروس مكتملة</small></div></div><div class="metric"><span class="metric-icon">🔥</span><div><strong>${profile.streak}</strong><small class="muted">أيام الاستمرار</small></div></div><div class="metric"><span class="metric-icon">🧪</span><div><strong>${profile.attempts}</strong><small class="muted">تحديات مجرّبة</small></div></div></div><div class="grid-2"><section class="card"><div class="flex between"><h3 class="mini-title">🗺️ تقدّمك في هذه المرحلة</h3><span class="stage-tag">${st.id}</span></div><div class="flex between small"><span>${E(st.name)}</span><strong>${finished}/2 دروس</strong></div><div style="margin:14px 0 20px">${progressBar(pct(finished,2))}</div>${st.id==='A0'?renderFoundationHome()+renderPhonicsHome():''}<div class="adventure-teaser"><strong>📖 مغامرتك في القراءة والمحادثة</strong><p class="small muted">قصتان وموقفان حواريان في كل مستوى، مع مراجعة القراءة.</p><button class="btn btn-outline btn-sm" data-action="open-adventure">افتح مغامرات مستواك ←</button></div><div class="stack">${stageLessons(st.id).map(l=>renderLessonShortcut(l)).join('')}</div>${gateUnlocked(st.id)?`<button class="btn btn-outline wide" style="margin-top:13px" data-action="start-gate" data-id="${st.id}">${profile.gatePass[st.id]?'أعد تحدّي المرحلة':'🏆 اختبار ترقية المرحلة'}</button>`:''}</section><section class="card"><h3 class="mini-title">🎯 مدرّبك الشخصي</h3><div class="flex" style="margin-bottom:17px"><div class="float-icon">🧠</div><div><strong>${weak?`لنقوِّ مهارة ${skills[weak]}`:'أنت تبني أساسًا رائعًا'}</strong><div class="small muted">${weak?'تدريب إضافي يساعدك في المهارة الأقل دقة حتى الآن.':'أنهِ درسك الأول لنكتشف ما تحتاجه أكثر.'}</div></div></div><button class="btn btn-mint wide" data-action="practice" data-mode="${weak==='listening'?'listen':weak==='writing'?'type':weak==='grammar'?'order':'general'}">ابدأ تدريبًا قصيرًا ⚡</button><div class="divider"></div>${renderDailyQuest()}<div class="divider"></div><h3 class="mini-title">🌈 بطاقة اليوم</h3><div class="tip">المواظبة أهم من السرعة. أكمل 5 دقائق تعلّم يوميًا، واستمع إلى الجمل وكرّرها بصوتك.</div><div style="margin-top:18px" class="flex between"><span class="small strong">ساحة الألعاب</span><button class="btn btn-outline btn-sm" data-action="nav" data-page="games">استكشف الألعاب ←</button></div></section></div>`;}
  function renderLessonShortcut(l){const ok=!!profile.completed[l.id],unlocked=stepUnlocked(l);return `<button class="lesson-card ${unlocked?'':'locked'}" data-action="start-lesson" data-id="${l.id}" ${unlocked?'':'disabled'}><span class="lesson-icon">${l.icon}</span><span class="grow"><strong>${E(l.title)}</strong><small>${ok?`⭐ أفضل نتيجة: ${profile.completed[l.id]}%`:unlocked?'جاهز للتعلّم':'مقفول حتى إكمال السابق'}</small></span><span>${ok?'✅':unlocked?'←':'🔒'}</span></button>`;}
  function renderPath(){const st=activeStage();return `<div class="road-head"><div><span class="eyebrow">YOUR LEARNING MAP</span><h2 class="section-title">كل خطوة تفتح لك عالمًا جديدًا 🗺️</h2><p class="muted small no-margin">ابدأ بالمستوى الذي رشحه لك الاختبار، وأنهِ وحدات المرحلة وتحدّي الترقية لفتح المرحلة التالية. يمكنك العودة للمراحل السابقة.</p></div><span class="chip">مستواك الآن ${st.id} ${st.emoji}</span></div>${stages.map((s,i)=>{const locked=i>idx(profile.stage),current=s.id===profile.stage,completed=!!profile.gatePass[s.id];const tiles=stageLessons(s.id).map((l,j)=>{const done=!!profile.completed[l.id],open=stepUnlocked(l);return `<button class="step-button ${done?'complete':open?'ready':''}" ${open?'':'disabled'} data-action="start-lesson" data-id="${l.id}"><span class="step-emoji">${done?'✅':open?l.icon:'🔒'}</span><span><strong>${j+1}. ${E(l.title)}</strong><small>${done?'مكتمل':open?'افتح الدرس':'مقفول'}</small></span></button>`;}).join('');const gateOpen=gateUnlocked(s.id);return `<section class="road-stage ${locked?'locked':current?'current':''}"><div class="road-stage-number"><span>${s.emoji}</span><strong>${E(s.id)}</strong></div><div><div class="flex wrap between"><div><span class="chip">${E(s.group)}</span><h3 style="font-size:21px;margin:5px 0 0">${E(s.name)}</h3><p class="muted small no-margin">${E(s.subtitle)}</p></div><span class="chip">${completed?'✅ تم اجتياز المرحلة':locked?'🔒 مقفولة':current?'🎯 مرحلتك الحالية':'مراجعة متاحة'}</span></div>${s.id==='A0'?renderFoundationPath()+renderPhonicsPath():''}<div class="adventure-stage-link">📖 ${stories.filter(t=>t.stage===s.id).length} قصص • 💬 ${dialogs.filter(t=>t.stage===s.id).length} محادثات <button class="btn btn-outline btn-sm" data-action="open-adventure" data-tab="stories">مغامرات المستوى</button></div><div class="stage-steps">${tiles}<button class="step-button ${completed?'complete':gateOpen?'ready':''}" ${gateOpen?'':'disabled'} data-action="start-gate" data-id="${s.id}"><span class="step-emoji">${completed?'🏅':gateOpen?'🏆':'🔒'}</span><span><strong>3. تحدّي الترقية</strong><small>${completed?'اجتزت التحدّي':gateOpen?'اختبر إتقانك':'أكمل الدرسين أولًا'}</small></span></button></div></div></section>`;}).join('')}`;}
  function renderFoundationPath(){return `<div class="foundation-path"><div class="flex between wrap"><div><strong>🔤 ابدأ بالحروف الإنجليزية من الصفر</strong><p class="small muted no-margin">أربع مجموعات • تعلم وسماع وكتابة • النجاح 7 من 8</p></div><span class="chip">${foundationCount()} / 4</span></div><div class="foundation-step-grid">${foundations.map((g,i)=>{const done=!!profile.foundations[g.id],open=foundationGroupAvailable(g);return `<button class="foundation-step ${done?'done':''}" data-action="open-foundation" data-id="${g.id}" ${open?'':'disabled'}><span class="f-emoji">${done?'✅':open?g.emoji:'🔒'}</span><strong>${i+1}. ${g.range}</strong><small>${done?'مكتملة':open?'تعلم ثم اختبر':'أكمل السابقة'}</small></button>`;}).join('')}</div></div>`;}
  function renderFoundations(){const passed=foundationCount(),isDone=foundationFinished();return `<div class="road-head"><div><span class="eyebrow">ABC ADVENTURE</span><h2 class="section-title">أكاديمية الحروف 🔤</h2><p class="muted small no-margin">من A إلى Z خطوة خطوة: احفظ شكل الحرف الكبير والصغير، استمع إلى اسمه وكلمته، ثم حل 8 أسئلة في كل مجموعة.</p></div><span class="chip">${passed} / 4 مجموعات</span></div><div class="card" style="margin-bottom:18px"><div class="flex between wrap"><strong>رحلتك نحو قراءة الكلمات</strong><span class="chip">${pct(passed,4)}%</span></div><div style="margin:12px 0">${progressBar(pct(passed,4))}</div><p class="small muted no-margin">${isDone?'🎉 رائع! انتقل الآن إلى مختبر الأصوات لتتعلّم تركيب الكلمات، أو راجع الحروف.':'اجتز المجموعات بالترتيب (7 إجابات صحيحة من 8) لتفتح مختبر الأصوات قبل دروس المستوى A0.'}</p></div><div class="grid-2">${foundations.map((g,i)=>{const open=foundationGroupAvailable(g),done=!!profile.foundations[g.id];return `<article class="foundation-tile ${done?'done':''}"><div class="flex between"><span class="foundation-hero-emoji">${g.emoji}</span><span class="chip">${done?'✅ أتقنت المجموعة':open?'متاحة للتعلم':'🔒 مقفلة'}</span></div><h3>${i+1}. ${g.title} <span class="en" lang="en">${g.range}</span></h3><p class="muted small">${g.goal}</p><button class="btn ${open?'btn-primary':'btn-outline'} wide" data-action="open-foundation" data-id="${g.id}" ${open?'':'disabled'}>${done?'مراجعة الحروف':open?'ابدأ التعلم ←':'أكمل السابقة أولًا'}</button></article>`;}).join('')}</div>${isDone?'<div class="card center" style="margin-top:16px"><h3 class="mini-title">🧩 أحسنت! الخطوة التالية: تركيب الكلمات</h3><button class="btn btn-primary" data-action="open-phonics">اذهب إلى مختبر الأصوات ←</button></div>':''}<div class="tip" style="margin-top:16px">ملاحظة: نطق الكلمات بصوت المتصفح للتدريب الأولي؛ معرفة أسماء الحروف وحدها لا تعني إتقان جميع أصوات الإنجليزية. ستجد مختبر دمج الأصوات والكلمات ضمن ساحة الألعاب ومسارك التعليمي.</div>`;}
  function renderFoundationLesson(){const g=foundations.find(x=>x.id===foundationPageId);if(!g)return renderFoundations();if(!foundationGroupAvailable(g))return renderFoundations();const rows=alphabet.filter(row=>g.letters.includes(row[0]));return `<div class="road-head"><div><button class="btn btn-ghost btn-sm" data-action="open-foundations">→ أكاديمية الحروف</button><span class="eyebrow">LEARN • LISTEN • PLAY</span><h2 class="section-title">${g.emoji} ${E(g.title)} <span class="en" lang="en">${E(g.range)}</span></h2><p class="muted small no-margin">${E(g.goal)}. اضغط البطاقة لسماع اسم الحرف وكلمته، ثم جرّب الاختبار.</p></div><span class="chip">${rows.length} حروف</span></div><div class="foundation-letter-grid">${rows.map(([upper,word,ar,emoji])=>`<article class="foundation-letter"><div class="foundation-letter-shapes"><span>${upper}</span><span>${upper.toLowerCase()}</span></div><span class="foundation-icon">${emoji}</span><div class="foundation-word" lang="en">${E(word)}</div><div class="small muted">${E(ar)}</div><button class="btn btn-outline btn-sm wide" data-action="say" data-say="${E(upper+'. '+word)}">🔊 استمع</button><p class="foundation-note">${E(alphabetNotes[upper]||'استمع ثم ردد الكلمة.')}</p></article>`).join('')}</div><div class="card foundation-quiz-entry"><div><h3 class="mini-title">🎯 هل تعرف هذه المجموعة؟</h3><p class="small muted no-margin">8 أسئلة متنوعة: شكل الحرف، أول حرف في كلمة، كتابة وتوصيل. اجتز 7 منها لفتح المجموعة التالية.</p></div><div class="flex wrap"><button class="btn btn-primary" data-action="foundation-quiz" data-id="${g.id}">ابدأ التحدّي (8 أسئلة) 🏆</button><button class="btn btn-outline" data-action="open-foundations">عودة للمجموعات</button></div></div>`;}
  function makeFoundationQuestions(group){
    const rows=alphabet.filter(row=>group.letters.includes(row[0]));
    const options=(answer,values)=>shuffled([answer,...shuffled(values.filter(x=>x!==answer)).slice(0,3)]);
    const selected=shuffled(rows);
    const item=(type,uid,fields)=>({type,uid:`${group.id}-${uid}`,skill:'alphabet',...fields});
    const questions=[];
    for(let i=0;i<2;i++){
      const [letter,word]=selected[i];const lower=letter.toLowerCase();
      questions.push(item('choice',`case-${letter}`,{q:`ما شكل الحرف الصغير المقابل لـ ${letter}؟`,options:options(lower,rows.map(x=>x[0].toLowerCase())),a:lower,explain:`${letter} هو الحرف الكبير و${lower} هو الحرف الصغير.`}));
    }
    for(let i=2;i<4;i++){
      const [letter,word,ar]=selected[i];
      questions.push(item('type',`write-${letter}`,{q:`اكتب الحرف الأول من كلمة ${word} (${ar})`,answers:[letter,letter.toLowerCase()],hint:'اكتب حرفًا إنجليزيًا واحدًا',explain:`${word} تبدأ بحرف ${letter}.`}));
    }
    for(let i=4;i<6;i++){
      const [letter,word,ar]=selected[i];
      questions.push(item(('speechSynthesis' in window)?'listen':'choice',`listen-${letter}`,{q:('speechSynthesis' in window)?'استمع للكلمة، ثم اختر حرفها الأول':`ما أول حرف في كلمة ${word}؟`,say:word,options:options(letter,rows.map(x=>x[0])),a:letter,explain:`الكلمة هي ${word} (${ar})، وتبدأ بحرف ${letter}.`}));
    }
    const first=rows.slice(0,3);
    questions.push(item('match','match-1',{q:'صِل الحرف الكبير بصيغته الصغيرة',pairs:shuffled(first.map(r=>[r[0],r[0].toLowerCase()])),explain:'كل حرف إنجليزي له شكل كبير وآخر صغير.'}));
    const target=rows[rows.length-2][0],next=rows[rows.length-1][0];
    questions.push(item('choice',`order-${target}`,{q:`أي حرف يأتي بعد ${target} في الأبجدية؟`,options:options(next,rows.map(x=>x[0])),a:next,explain:`يأتي ${next} بعد ${target}.`}));
    return shuffled(questions);
  }
  function startFoundationQuiz(id){const g=foundations.find(x=>x.id===id);if(!g||!foundationGroupAvailable(g)){toast('أكمل المجموعة السابقة أولًا.');return;}startQuiz({mode:'foundation',id:g.id,title:`حروف ${g.range}`,items:makeFoundationQuestions(g)});}

  function renderPhonicsHome(){return `<div class="foundation-inline"><div class="flex between wrap"><div><strong>🧩 مختبر الأصوات</strong><div class="small muted">${phonicsCount()} / ${phonics.length} وحدات أصوات قصيرة</div></div><button class="btn btn-outline btn-sm" data-action="open-phonics">${phonicsFinished()?'راجع الأصوات':'ابدأ تركيب الكلمات'}</button></div>${progressBar(pct(phonicsCount(),phonics.length))}</div>`;}
  function renderPhonicsPath(){return `<div class="foundation-path"><div class="flex between wrap"><div><strong>🧩 خطوة القراءة: أصوات الحروف القصيرة</strong><p class="muted small no-margin">تعلّم ثم اسمع وركّب كلمات من ثلاثة أصوات. النجاح 7 من 8.</p></div><button class="btn btn-outline btn-sm" data-action="open-phonics">افتح المختبر ←</button></div><div class="phonics-mini-row">${phonics.map((g,i)=>`<button class="phonics-dot ${profile.phonics[g.id]?'done':''}" data-action="open-phonic" data-id="${g.id}" ${phonicsAvailable(g)?'':'disabled'}><strong>${g.vowel.toUpperCase()}</strong><small>${profile.phonics[g.id]?'✓':phonicsAvailable(g)?'ابدأ':'🔒'}</small></button>`).join('')}</div></div>`;}
  function renderDailyQuest(){const d=dailyInfo(),n=Math.min(8,d.correct);return `<section class="daily-quest"><div class="flex between wrap"><strong>🎯 مهمة اليوم: 8 إجابات صحيحة</strong><span class="chip">${n}/8 ${d.bonusClaimed?'✅':''}</span></div><div style="margin:10px 0">${progressBar(pct(n,8))}</div><p class="small muted no-margin">أكمل المهمة لتحصل على 40 نقطة إضافية مرة واحدة اليوم. لا يلزم إنهاءها دفعة واحدة.</p><div class="flex wrap" style="margin-top:12px"><button class="btn btn-outline btn-sm" data-action="practice" data-mode="review">🧠 مراجعات مستحقة: ${dueReviews().length}</button><button class="btn btn-outline btn-sm" data-action="practice" data-mode="focus">🎯 تقوية أضعف مهارة</button></div></section>`;}
  function renderPhonics(){const done=phonicsCount();return `<div class="road-head"><div><span class="eyebrow">SOUND LAB • BLENDING</span><h2 class="section-title">🧩 مختبر أصوات الكلمات</h2><p class="small muted no-margin">تعلم صوت الحرف داخل الكلمة، لا اسمه فقط. نبدأ بالكلمات القصيرة ذات ثلاثة أحرف (CVC).</p></div><span class="chip">${done} / ${phonics.length} وحدات مكتملة</span></div><section class="card" style="margin-bottom:16px"><h3 class="mini-title">🎯 هدفك: اسمع ← حلّل ← ادمج ← اقرأ</h3><p class="small muted" style="line-height:1.9">الكلمة <span lang="en" class="en">cat</span> تتكوّن من ثلاثة أصوات <span lang="en" class="en">/k/ + /æ/ + /t/</span>؛ درّب عينيك على الحروف وأذنك على الكلمة الكاملة.</p>${progressBar(pct(done,phonics.length))}<p class="footnote">الصوت مولّد بأداة النطق في المتصفح، وليس تسجيلًا بشريًا ولا تحليلًا آليًا لدقة نطق الطالب.</p></section><div class="phonics-grid">${phonics.map((g,i)=>{const open=phonicsAvailable(g),ok=!!profile.phonics[g.id];return `<article class="phonic-unit ${ok?'done':''}"><div class="flex between"><span class="phonics-icon">${g.emoji}</span><span class="chip">${ok?'✅ مكتملة':open?'🎯 متاحة':'🔒 مقفلة'}</span></div><div class="en phonics-vowel" lang="en">${g.vowel.toUpperCase()} <small>${E(g.ipa)}</small></div><h3>${E(g.title)}</h3><p class="small muted">${E(g.hint)}</p><div class="word-samples" dir="ltr">${g.words.map(w=>`<span>${E(w.word)}</span>`).join('')}</div><button class="btn ${open?'btn-primary':'btn-outline'} wide" data-action="open-phonic" data-id="${g.id}" ${open?'':'disabled'}>${ok?'أعد المراجعة':open?'تعلم والعب ←':'أكمل السابقة'}</button></article>`;}).join('')}</div>`;}
  function renderPhonicLesson(){const g=phonics.find(x=>x.id===phonicsPageId);if(!g||!phonicsAvailable(g))return renderPhonics();return `<div class="road-head"><div><button class="btn btn-ghost btn-sm" data-action="open-phonics">→ وحدات الأصوات</button><span class="eyebrow">LISTEN • BLEND • READ</span><h2 class="section-title">${g.emoji} ${E(g.title)} <span class="en" lang="en">${E(g.ipa)}</span></h2><p class="muted small no-margin">${E(g.hint)}</p></div><span class="chip">4 كلمات • 8 تحديات</span></div><section class="card" style="margin-bottom:16px"><h3 class="mini-title">💡 طريقة الدمج</h3><div class="blend-demo" dir="ltr"><span>c</span><b>+</b><span>a</span><b>+</b><span>t</span><b>→</b><strong>cat 🐱</strong></div><p class="small muted">انظر إلى كل حرف، وردّد صوته القصير، ثم قل الكلمة بسرعة متصلة. اضغط «اسمع» للتأكد من نطق الكلمة.</p></section><div class="phonics-grid">${g.words.map((w,i)=>`<article class="phonic-word-card"><div class="flex between"><span class="chip">كلمة ${i+1} / 4</span><span class="phonics-icon">${w.emoji}</span></div><div class="phonics-spelling en" dir="ltr" lang="en">${E(w.word.slice(0,1))} <span>${E(w.word.slice(1,2))}</span> ${E(w.word.slice(2))}</div><div class="phonics-ipa" dir="ltr" lang="en">${w.parts.map(x=>`<span>${E(x)}</span>`).join(' + ')}</div><strong class="phonics-translation">${E(w.ar)}</strong><button class="btn btn-mint btn-sm wide" data-action="say" data-say="${E(w.word)}">🔊 اسمع ${E(w.word)}</button></article>`).join('')}</div><section class="card center" style="margin-top:18px"><h3 class="mini-title">🏆 هل تستطيع تركيب هذه الكلمات؟</h3><p class="small muted">4 ألعاب تركيب أحرف، وسؤالان للاستماع، وسؤال للمعنى، وسؤال للكتابة. النجاح 7 من 8.</p><button class="btn btn-primary" data-action="phonics-quiz" data-id="${g.id}">ابدأ تحدّي الأصوات ←</button></section>`;}
  function makePhonicsQuestions(g){
    const w=g.words;const questions=[];
    for(const item of w){
      const letters=[...item.word,item.extra];
      questions.push({type:'blend',q:`ركّب الكلمة التي تعني «${item.ar}» بعد الاستماع`,say:item.word,tiles:shuffled(letters),answer:item.word,skill:'alphabet',explain:`${item.word} = ${item.ar}. الأصوات: ${item.parts.join(' + ')}.`});
    }
    for(const item of w.slice(0,2)){
      questions.push({type:'listen',q:'استمع: ما الكلمة التي سمعتها؟',say:item.word,options:shuffled(w.map(z=>z.word)),a:item.word,skill:'listening',explain:`${item.word} تعني «${item.ar}».`});
    }
    const target=w[2];
    questions.push({type:'choice',q:`اختر الكلمة الإنجليزية التي تعني «${target.ar}»`,options:shuffled(w.map(z=>z.word)),a:target.word,skill:'vocab',explain:`${target.word} = ${target.ar}.`});
    const last=w[3];
    questions.push({type:'type',q:`اكتب الكلمة الإنجليزية التي تعني «${last.ar}»`,answers:[last.word],hint:`تبدأ بالحرف ${last.word[0].toUpperCase()} وتتكون من 3 أحرف`,skill:'writing',explain:`${last.word} = ${last.ar}.`});
    return prepareQuestions(questions,g.id);
  }
  function startPhonicsQuiz(id){const g=phonics.find(x=>x.id===id);if(!g||!phonicsAvailable(g)){toast('أكمل الوحدة السابقة أولًا.');return;}startQuiz({mode:'phonics',id,title:'تحدّي صوت '+g.vowel.toUpperCase(),items:makePhonicsQuestions(g)});}


  /* V4: level-appropriate stories, branching dialogue simulations and advanced patterns.
     These bonus missions do not retroactively lock V3 core lessons or alter CEFR placement. */
  const isAvailableStage=stage => idx(stage)<=idx(profile.stage);
  const stageSequence=(items,item)=>items.filter(x=>x.stage===item.stage);
  function adventureOpen(items,item,progress){
    if(!isAvailableStage(item.stage))return false;
    const group=stageSequence(items,item),i=group.findIndex(x=>x.id===item.id);
    return i===0||!!progress[group[i-1].id];
  }
  const doneAdventures=()=>Object.keys(profile.stories).length+Object.keys(profile.dialogues).length;
  function adventureCard(item,kind){
    const map=kind==='story'?profile.stories:kind==='dialog'?profile.dialogues:profile.readingPatterns;
    const all=kind==='story'?stories:kind==='dialog'?dialogs:patterns;
    const open=kind==='pattern'?isAvailableStage(item.stage)&&(item.stage!=='A0'||phonicsFinished()):adventureOpen(all,item,map);
    const done=!!map[item.id],label=kind==='story'?'📖 قصة':kind==='dialog'?'💬 محادثة':'🔤 قاعدة قراءة';
    return `<article class="adventure-card ${done?'adventure-done':''} ${open?'':'adventure-locked'}"><div class="flex between"><span class="adventure-emoji">${item.emoji}</span><span class="chip">${E(item.stage)} ${done?'✅':open?'🎯':'🔒'}</span></div><div class="tiny muted">${label}</div><h3>${E(item.titleAr)}</h3><div class="en" lang="en">${E(item.title)}</div><p class="small muted">${kind==='story'?`${item.paras.length} مقاطع • 5 أسئلة فهم ومفردات`:kind==='dialog'?'3 مواقف لاتخاذ القرار':'4 كلمات • 6 أسئلة تطبيقية'}</p><button class="btn ${open?'btn-primary':'btn-outline'} btn-sm wide" data-action="${kind==='story'?'read-story':kind==='dialog'?'start-dialog':'open-pattern'}" data-id="${E(item.id)}" ${open?'':'disabled'}>${done?'أعد التدريب':open?'ابدأ المهمة ←':'يُفتح بعد المرحلة السابقة'}</button></article>`;
  }
  function renderAdventure(){
    const tabs=[['stories','📖 القصص'],['dialogues','💬 المحادثات'],['patterns','🔤 قراءة متقدمة']];
    const source=adventureTab==='stories'?stories:adventureTab==='dialogues'?dialogs:patterns;
    const kind=adventureTab==='stories'?'story':adventureTab==='dialogues'?'dialog':'pattern';
    return `<div class="road-head"><div><span class="eyebrow">LINGOQUEST • ADVENTURE V4</span><h2 class="section-title">📖 جزيرة القصص والمحادثات</h2><p class="small muted no-margin">تعلم من مواقف واقعية وقصص أصلية مكتوبة لمستواك. المستويات الأعلى مقفلة حتى ترقيتك.</p></div><span class="chip">🏅 ${doneAdventures()} / ${stories.length+dialogs.length} مهمة ناجحة</span></div><div class="adventure-tabs">${tabs.map(([k,t])=>`<button class="adventure-tab ${adventureTab===k?'selected':''}" data-action="adventure-tab" data-tab="${k}">${t}</button>`).join('')}</div><div class="adventure-help">${kind==='story'?'📘 اقرأ القصة واستمع لكل مقطع وأظهر الترجمة عند الحاجة؛ أجب عن 5 أسئلة للنجاح (4/5).':kind==='dialog'?'🎭 اختر أفضل رد في 3 جولات. تتغير استجابة الشخصية وفق اختيارك، والنجاح بإجابتين صحيحتين على الأقل.':'🔠 اقرأ القاعدة واستمع للأمثلة، ثم أكمل اختبار 6 أسئلة (5/6).'} المواقف قصصية ومبرمجة مسبقًا، وليست محادثة ذكاء اصطناعي مباشرة.</div>${stages.filter(s=>source.some(v=>v.stage===s.id)).map(stage=>`<section class="adventure-stage"><div class="flex between wrap"><h3>${stage.emoji} مستوى ${E(stage.id)} — ${E(stage.name)}</h3><span class="chip">${isAvailableStage(stage.id)?'متاح حسب مستواك':'🔒 بعد الترقية'}</span></div><div class="adventure-grid">${source.filter(a=>a.stage===stage.id).map(x=>adventureCard(x,kind)).join('')}</div></section>`).join('')}`;
  }
  function renderStory(){
    const s=stories.find(x=>x.id===storyId);if(!s||!adventureOpen(stories,s,profile.stories))return renderAdventure();
    return `<div class="road-head"><div><button class="btn btn-ghost btn-sm" data-action="open-adventure">→ العودة للمغامرات</button><span class="eyebrow">GRADED READING • ${E(s.stage)}</span><h2 class="section-title">${s.emoji} ${E(s.titleAr)}</h2><p class="en" lang="en">${E(s.title)}</p></div><span class="chip">📘 ${s.paras.length} مقاطع</span></div><section class="card story-paper"><div class="flex between wrap"><span class="chip">اقرأ ← اسمع ← افهم</span><button class="btn btn-outline btn-sm" data-action="toggle-translation">${showTranslation?'إخفاء الترجمة':'إظهار الترجمة'} 🌐</button></div><div class="story-paragraphs">${s.paras.map((p,i)=>`<div class="story-paragraph"><div class="flex between" style="align-items:start;gap:12px"><p class="en story-english" lang="en" dir="ltr">${E(p.en)}</p><button class="btn btn-outline btn-sm" data-action="say" data-say="${E(p.en)}" aria-label="استمع إلى الفقرة ${i+1}">🔊</button></div>${showTranslation?`<p class="small muted">${E(p.ar)}</p>`:''}</div>`).join('')}</div><button class="btn btn-mint btn-sm" data-action="say" data-say="${E(s.paras.map(p=>p.en).join(' '))}">🔊 استمع للقصة كاملة</button></section><section class="card" style="margin-top:16px"><h3 class="mini-title">🗝️ مفاتيح القصة</h3><div class="story-vocab">${s.vocab.map(v=>`<button class="vocab-pill" data-action="say" data-say="${E(v.en)}">🔊 <span class="en" lang="en">${E(v.en)}</span> — ${E(v.ar)}</button>`).join('')}</div><div class="divider"></div><p class="muted small">5 أسئلة عن المعنى والتفاصيل والمفردات • اجتز 4 من 5 لفتح القصة التالية.</p><button class="btn btn-primary" data-action="story-quiz" data-id="${s.id}">🎯 ابدأ أسئلة القصة ←</button></section>`;
  }
  function storyQuestions(s){
    const original=s.questions.map(x=>({type:'choice',q:x.q,options:shuffled(x.options),a:x.a,skill:'reading',explain:'ارجع إلى القصة واقرأ السياق لتثبت المعنى.'}));
    const distractor=[...new Set(stories.flatMap(x=>x.vocab.map(v=>v.ar)).filter(ar=>!s.vocab.some(v=>v.ar===ar)))];
    for(const v of s.vocab){original.push({type:'choice',q:`ما معنى الكلمة “${v.en}” في القصة؟`,options:shuffled([v.ar,...shuffled(distractor).slice(0,3)]),a:v.ar,skill:'vocab',explain:`${v.en} = ${v.ar}`});}
    return prepareQuestions(original,s.id);
  }
  function beginStoryQuiz(id){const s=stories.find(x=>x.id===id);if(!s||!adventureOpen(stories,s,profile.stories)){toast('أكمل القصة السابقة أولًا.');return;}startQuiz({mode:'story',id:s.id,title:'تحدّي قصة '+s.titleAr,items:storyQuestions(s)});}
  function renderDialogue(){
    const d=dialogs.find(x=>x.id===dialogId);if(!d||!adventureOpen(dialogs,d,profile.dialogues))return renderAdventure();
    const done=dialogTurn>=d.steps.length,step=d.steps[dialogTurn];
    return `<div class="road-head"><div><button class="btn btn-ghost btn-sm" data-action="open-adventure">→ العودة للمغامرات</button><span class="eyebrow">INTERACTIVE ROLE-PLAY • ${E(d.stage)}</span><h2 class="section-title">${d.emoji} ${E(d.titleAr)}</h2><p class="muted small no-margin">تخيّل أنك الشخصية الرئيسية. اختر ردك؛ ستتفاعل الشخصية مع قرارك.</p></div><span class="chip">${Math.min(dialogTurn+1,d.steps.length)} / ${d.steps.length} 🎭</span></div><section class="card dialogue-card">${progressBar(pct(dialogTurn,d.steps.length))}<div class="dialogue-messages">${dialogLog.map(m=>`<div class="dialogue-line ${m.who==='you'?'me':m.who==='feedback'?'note':'bot'}"><span class="dialogue-avatar">${m.who==='you'?'🧑':m.who==='feedback'?'💡':'🦊'}</span><div><div class="en" lang="en" dir="ltr">${E(m.text)}</div>${m.ar?`<div class="small muted">${E(m.ar)}</div>`:''}</div></div>`).join('')}${!done?`<div class="dialogue-line bot"><span class="dialogue-avatar">🦊</span><div><div class="en" lang="en" dir="ltr">${E(step.bot)}</div><div class="small muted">${E(step.hint)}</div><button class="btn btn-outline btn-sm" data-action="say" data-say="${E(step.bot)}">🔊 استمع</button></div></div>`:''}</div>${done?`<div class="dialogue-end"><h3>${dialogCorrect>=2?'🏆 أحسنت! أنجزت المهمة':'🔁 جرّب الحوار مرة أخرى'}</h3><p>اخترت ${dialogCorrect} ردود صحيحة من ${d.steps.length}. ${dialogCorrect>=2?'يمكنك متابعة المهمة التالية.':'راجع العبارات وجرب مرة ثانية.'}</p><div class="flex wrap"><button class="btn btn-primary" data-action="start-dialog" data-id="${d.id}">إعادة المحادثة</button><button class="btn btn-outline" data-action="open-adventure">العودة للمغامرات</button></div></div>`:dialogAnswered?`<div class="dialog-feedback ${dialogAnswered.correct?'right':'wrong'}"><strong>${dialogAnswered.correct?'✅ رد ممتاز':'💡 تعلّم الرد الأنسب'}</strong><div>${E(dialogAnswered.explain)}</div><div><b>أفضل رد:</b> <span class="en" lang="en">${E(step.good)}</span></div></div><button class="btn btn-primary wide" data-action="dialog-next">${dialogTurn===d.steps.length-1?'نتيجة المحادثة 🏆':'التالي ←'}</button>`:`<h3 class="mini-title">💬 ما الرد المناسب؟</h3><div class="dialogue-options">${shuffled([step.good,...step.wrong]).map(x=>`<button class="dialogue-option en" dir="ltr" lang="en" data-action="dialog-answer" data-value="${E(x)}">${E(x)}</button>`).join('')}</div>`}</section><p class="small muted" style="margin-top:12px">المحادثة محاكاة بخيارات محددة، وليست محادثة حرة أو تقييمًا لنطق المتعلم.</p>`;
  }
  function startDialogue(id){const d=dialogs.find(x=>x.id===id);if(!d||!adventureOpen(dialogs,d,profile.dialogues)){toast('أكمل المحادثة السابقة أولًا.');return;}dialogId=id;dialogTurn=0;dialogCorrect=0;dialogAnswered=null;dialogLog=[];page='dialogPlay';render();}
  function answerDialogue(value){const d=dialogs.find(x=>x.id===dialogId),step=d?.steps[dialogTurn];if(!step||dialogAnswered)return;if(![step.good,...step.wrong].includes(value))return;const correct=value===step.good;if(correct)dialogCorrect++;dialogAnswered={correct,explain:step.explain};dialogLog.push({who:'you',text:value});dialogLog.push({who:'bot',text:correct?step.reply:'Let me help you choose a clearer reply.',ar:correct?'رد مناسب للسياق.':'اختيار غير مناسب؛ اقرأ التوضيح.'});render();}
  function nextDialogue(){const d=dialogs.find(x=>x.id===dialogId);if(!dialogAnswered||!d)return;const wasCorrect=dialogAnswered.correct;addStats('listening',wasCorrect);dialogTurn++;dialogAnswered=null;
    if(dialogTurn===d.steps.length){profile.attempts++;touchActivity();const passed=dialogCorrect>=2;let earned=passed?(profile.dialogues[d.id]?15:60):10;profile.xp+=earned;profile.history.unshift({mode:'dialogue',id:d.id,score:pct(dialogCorrect,d.steps.length),date:now(),passed});profile.history=profile.history.slice(0,55);if(passed)profile.dialogues[d.id]={score:Math.max(profile.dialogues[d.id]?.score||0,pct(dialogCorrect,d.steps.length)),date:now()};const daily=dailyInfo();daily.correct+=dialogCorrect;daily.total+=d.steps.length;if(daily.correct>=8&&!daily.bonusClaimed){daily.bonusClaimed=true;profile.xp+=40;}profile.daily=daily;store();toast(passed?`🏅 نجحت في المحادثة! +${earned} XP`:'حاول مرة أخرى بعد مراجعة أفضل الردود.');}
    render();}
  function renderPattern(){const p=patterns.find(x=>x.id===patternId);if(!p||!isAvailableStage(p.stage)||(p.stage==='A0'&&!phonicsFinished()))return renderAdventure();return `<div class="road-head"><div><button class="btn btn-ghost btn-sm" data-action="open-adventure">→ العودة للمغامرات</button><span class="eyebrow">READING PATTERN • ${E(p.stage)}</span><h2 class="section-title">${p.emoji} ${E(p.title)}</h2></div><span class="chip">6 أسئلة</span></div><section class="card"><h3>🔍 القاعدة</h3><p class="muted">${E(p.explain)}</p><div class="pattern-grid">${p.words.map(([w,ar,key])=>`<div class="pattern-word"><strong class="en" lang="en" dir="ltr">${E(w)}</strong><span class="small muted">${E(ar)}</span><span class="chip en">${E(key)}</span><button class="btn btn-outline btn-sm" data-action="say" data-say="${E(w)}">🔊 استمع</button></div>`).join('')}</div><p class="muted small">النطق يعتمد على الأصوات المتوفرة في المتصفح، وقد يختلف حسب اللكنة.</p><button class="btn btn-primary" data-action="pattern-quiz" data-id="${p.id}">ابدأ اختبار القراءة ←</button></section>`;}
  function startPatternQuiz(id){const p=patterns.find(x=>x.id===id);if(!p||!isAvailableStage(p.stage)||(p.stage==='A0'&&!phonicsFinished())){toast('هذه الوحدة لم تُفتح بعد.');return;}const w=p.words;const items=w.map(([word,ar])=>({type:'listen',q:'استمع ثم اختر الكلمة الصحيحة',say:word,options:shuffled(w.map(x=>x[0])),a:word,skill:'reading',explain:`${word} تعني ${ar}.`}));for(const [word,ar] of [w[0],w[2]])items.push({type:'choice',q:`أي كلمة تعني «${ar}»؟`,options:shuffled(w.map(x=>x[0])),a:word,skill:'vocab',explain:`${word} = ${ar}`});startQuiz({mode:'readingPattern',id:p.id,title:'تحدّي '+p.title,items:prepareQuestions(items,p.id)});}

  const gameDefs=[['focus','🎯','تحدّي نقاط ضعفي','تدريب مخصص على المهارة التي تحتاج إلى تعزيز وفق إجاباتك.'],['general','⚡','السباق السريع','أسئلة متنوعة في المفردات والقواعد، اجمع النقاط في دقائق.'],['listen','🎧','صائد الأصوات','استمع للعبارات الإنجليزية واختر ما سمعته أو معناها.'],['order','🧩','مهندس الجمل','رتّب الكلمات والحروف لتكوين جمل صحيحة.'],['type','✍️','تحدّي الكتابة','اكتب الكلمات والتراكيب بنفسك دون خيارات جاهزة.'],['match','🔗','وصّل الكلمات','طابق الكلمات مع معانيها بسرعة ودقة.'],['review','🧠','مراجعة أخطائي','تدرّب على أسئلتك السابقة التي تحتاج إلى تقوية.']];
  function renderGames(){return `<div class="road-head"><div><span class="eyebrow">PLAYGROUND</span><h2 class="section-title">العب لتتعلّم… وتعلّم لتفوز 🎮</h2><p class="muted small no-margin">تُستخرج التحديات من دروس المستويات المفتوحة لديك؛ كل إجابة صحيحة تمنحك نقاطًا.</p></div><span class="chip">🧠 ${dueReviews().length} مراجعات مستحقة</span></div><div class="grid-3"><article class="game-card"><div class="game-emoji">📖</div><h3>قصص ومحادثات V4</h3><p>12 قصة بمستويات متدرجة، و12 موقفًا تفاعليًا مع تغذية راجعة.</p><button class="btn btn-primary btn-sm" data-action="open-adventure">ابدأ المهمة ←</button></article><article class="game-card"><div class="game-emoji">🧩</div><h3>مختبر الأصوات والكلمات</h3><p>اسمع كلمات قصيرة، وادمج ثلاثة أحرف لتكوينها، وأتقن أصوات A وE وI وO وU.</p><button class="btn btn-primary btn-sm" data-action="open-phonics">اكتشف الأصوات ←</button></article><article class="game-card"><div class="game-emoji">🔤</div><h3>مغامرة الحروف A–Z</h3><p>تعلم أسماء وأشكال الحروف، وأنصت للكلمات، ثم اجتز تحديات الحروف الأربعة.</p><button class="btn btn-outline btn-sm" data-action="open-foundations">ابدأ من الصفر ←</button></article>${gameDefs.map(([mode,icon,name,desc])=>`<article class="game-card"><div class="game-emoji">${icon}</div><h3>${name}</h3><p>${desc}</p><button class="btn btn-outline btn-sm" data-action="practice" data-mode="${mode}">العب الآن ←</button></article>`).join('')}<article class="game-card"><div class="game-emoji">🎙️</div><h3>مدرّب النطق</h3><p>اسمع جملة وقلّدها. اختبر الميكروفون إن كان متاحًا على متصفحك.</p><button class="btn btn-outline btn-sm" data-action="open-speak">تدرب على النطق ←</button></article></div><section class="card" style="margin-top:20px"><div class="flex between wrap"><div><span class="eyebrow">ABC CORNER</span><h3 class="section-title" style="margin-bottom:2px">حديقة الحروف الإنجليزية 🔤</h3><p class="small muted no-margin">اضغط أي حرف لتسمع اسمه وكلمة تبدأ به.</p></div><span class="chip">26 حرفًا</span></div><div class="alphabet-grid">${alphabet.map(([letter,word,ar,emoji])=>`<button class="letter" data-action="letter" data-letter="${letter}" aria-label="انطق ${E(letter)} ${E(word)}"><div class="emoji">${emoji}</div><div class="glyph">${letter}</div><div class="word">${E(word)}</div><div class="tiny muted">${E(ar)}</div></button>`).join('')}</div></section>`;}
  function renderSpeak(){const seq=pronunciation[profile.stage]||pronunciation.A0,p=seq[pronounceIndex%seq.length];return `<div class="quiz-frame"><button class="btn btn-ghost btn-sm" data-action="nav" data-page="games">→ العودة للألعاب</button><div class="card" style="margin-top:14px"><div class="eyebrow">PRONUNCIATION PRACTICE</div><h2 class="section-title">🎙️ استمع ثم تحدّث</h2><p class="muted">تدريب اختياري على النطق، لا يؤثر في نتيجة الدروس أو الترقية.</p><div class="speaking-box"><div class="mic-emoji">🎤</div><div class="small">الجملة ${pronounceIndex%seq.length+1} من ${seq.length}</div><h2>${E(p)}</h2><button class="btn btn-white" data-action="say" data-say="${E(p)}">🔊 استمع للجملة</button></div><div class="flex wrap" style="justify-content:center;margin:22px 0"><button class="btn btn-primary" data-action="mic">🎙️ جرّب تسجيل النطق</button><button class="btn btn-outline" data-action="speak-next">الجملة التالية ←</button></div>${micStatus?`<div class="tip">${E(micStatus)}</div>`:''}<p class="footnote">التعرّف على الكلام غير مدعوم في جميع المتصفحات، وقد يرسل الصوت إلى خدمة المتصفح. لا نحتفظ بتسجيلات صوتية.</p></div></div>`;}
  function renderAchievements(){const a=[['first','🚀','المستكشف الأول','أكملت تحديد المستوى',!!profile.placementDone],['lesson','📚','أول درس','اجتزت أي درس بنجاح',Object.keys(profile.completed).length>0],['phonics','🧩','صانع الكلمات','اجتزت وحدات الصوت الخمس',phonicsFinished()],['review','🧠','عالم المراجعة','مارست المراجعة الذكية',profile.history.some(h=>h.id==='review')],['xp','🌟','جامع النجوم','جمعت 100 نقطة خبرة',profile.xp>=100],['streak','🔥','ثلاثة أيام','تعلمت في ثلاثة أيام متتالية',profile.streak>=3],['practice','🎮','محترف الألعاب','أنهيت عشرة تحديات تدريب',profile.practiceCount>=10],['a0','🌱','انطلاقة قوية','اجتزت مرحلة A0',!!profile.gatePass.A0],['b1','🧭','مستكشف بارع','اجتزت مرحلة B1',!!profile.gatePass.B1],['c1','👑','ملك اللغة','اجتزت تحدّي C1 التجريبي',!!profile.gatePass.C1]];return `<div class="road-head"><div><span class="eyebrow">TROPHY ROOM</span><h2 class="section-title">إنجازاتك تروي قصتك 🏆</h2><p class="small muted no-margin">${a.filter(x=>x[4]).length} من ${a.length} أوسمة متاحة</p></div><span class="chip">⭐ ${profile.xp} XP</span></div><div class="grid-3">${a.map(([,emoji,title,desc,done])=>`<div class="achievement ${done?'':'locked'}"><div class="a-emoji">${emoji}</div><h3>${title}</h3><p>${desc}</p><div class="chip" style="margin-top:12px">${done?'✅ حصلت عليه':'🔒 لم يُفتح بعد'}</div></div>`).join('')}</div><section class="card" style="margin-top:18px"><h3 class="mini-title">📈 إحصائيات المهارات</h3><div class="skill-bars">${skillSummaryRows(profile.skillStats)}</div></section>`;}
  function renderSettings(){return `<div class="grid-2"><section class="card"><h2 class="section-title">👤 بطاقة المتعلم</h2><div class="flex"><div class="avatar">🧑‍🚀</div><div><strong>${E(profile.name)}</strong><div class="muted small">${E(activeStage().name)} • ${E(profile.stage)}</div></div></div><div class="divider"></div><div class="stack small"><div class="flex between"><span>تاريخ البداية</span><strong>${E(profile.createdAt.slice(0,10))}</strong></div><div class="flex between"><span>نقاط الخبرة</span><strong>${profile.xp} XP</strong></div><div class="flex between"><span>إجمالي التحديات</span><strong>${profile.attempts}</strong></div></div><button class="btn btn-outline wide" data-action="switch-profile" style="margin-top:20px">🔄 تبديل المتعلم</button></section><section class="card"><h2 class="section-title">🛠️ أدوات تجربة النسخة</h2><p class="muted small">إذا أردت اختبار مسار مختلف يمكنك إعادة الاختبار. تنبيه: إعادة الاختبار تمسح نتائج الدروس والتقدم لهذا المتعلم فقط.</p><button class="btn btn-outline wide" data-action="ask-reset">إعادة اختبار تحديد المستوى</button><div class="divider"></div><p class="small muted">الخصوصية: التطبيق لا يتصل بقاعدة بيانات، ولا يحوي مفتاح Gemini API، ولا يرسل أسماء المتعلمين لخادمنا. تُخزن النتائج محليًا ويمكن فقدها عند حذف بيانات المتصفح.</p><button class="btn btn-ghost wide" data-action="export-progress">📥 تصدير بيانات التقدّم (JSON)</button><button class="btn btn-outline wide" data-action="pick-import" style="margin-top:9px">📂 استيراد بيانات من ملف V2 أو V3 أو V4</button><input type="file" id="import-file" accept=".json,application/json" hidden></section></div>`;}
  function startPlacement(){placementSession={index:0,answers:[]};page='placement';render();}
  function answerPlacement(i){if(!placementSession)return;const q=placement[placementSession.index];const correct=q.options[Number(i)]===q.a;placementSession.answers.push({correct,stage:q.stage,skill:q.skill});placementSession.index++;if(placementSession.index===placement.length){completePlacement();}else{render();}}
  function completePlacement(){const a=placementSession.answers,sections={A0:0,B1:0,C1:0},stats={};a.forEach(x=>{if(x.correct)sections[x.stage]++;if(!stats[x.skill])stats[x.skill]={right:0,total:0};stats[x.skill].total++;if(x.correct)stats[x.skill].right++;});let stage='A0';if(sections.A0>=5){stage='A1';if(sections.B1>=3)stage='A2';if(sections.B1>=6)stage='B1';if(sections.B1>=6&&sections.C1>=3)stage='B2';if(sections.B1>=6&&sections.C1>=6)stage='C1';}profile.stage=stage;profile.placementDone=true;profile.placementResult={sections,stats,date:now()};profile.skillStats=structuredClone(stats);profile.xp+=50;touchActivity();placementSession=null;page='placementResult';store();render();}
  function prepareQuestions(items,prefix){return items.map((q,i)=>({...q,uid:`${prefix}-${i}`}));}
  function startLesson(id){const l=lessons.find(x=>x.id===id);if(!l||!stepUnlocked(l)){toast('أكمل الدرس السابق لفتح هذا التحدّي.');return;}activeLessonId=id;openedCards.clear();quiz=null;result=null;page='lessonPreview';render();}
  function beginLesson(id){const l=lessons.find(x=>x.id===id);if(!l||!stepUnlocked(l)){toast('هذا الدرس غير متاح بعد.');return;}startQuiz({mode:'lesson',id:l.id,title:l.title,items:prepareQuestions(l.items,l.id)});}
  function startGate(stage){if(!gateUnlocked(stage)){toast('أكمل درسي هذه المرحلة أولًا.');return;}const items=stageLessons(stage).flatMap((l,j)=>j===0?[l.items[1],l.items[2],l.items[4]]:[l.items[0],l.items[3],l.items[5]]);startQuiz({mode:'gate',id:stage,title:'تحدّي الترقية • '+stage,items:prepareQuestions(items,stage+'-gate')});}
  function practice(mode){const allowed=lessons.filter(l=>idx(l.stage)<=idx(profile.stage)).flatMap(l=>prepareQuestions(l.items,l.id));let pool=allowed;
    if(mode==='review'){pool=dueReviews().map(([uid,v])=>({...v.item,uid}));if(!pool.length){toast('لا توجد مراجعات مستحقة الآن. ارجع عندما يحين موعد المراجعة التالية.');return;}}
    else if(mode==='focus'){const weak=weakSkill();pool=weak?allowed.filter(q=>q.skill===weak):allowed;}
    else if(mode==='listen')pool=allowed.filter(q=>q.type==='listen');
    else if(mode==='order')pool=allowed.filter(q=>q.type==='order');
    else if(mode==='type')pool=allowed.filter(q=>q.type==='type');
    else if(mode==='match')pool=allowed.filter(q=>q.type==='match');
    if(!pool.length){toast('لا توجد أسئلة كافية لهذه اللعبة بعد.');return;}
    const labels={focus:'تحدّي نقاط ضعفي',review:'مراجعة أخطائي',listen:'صائد الأصوات',order:'مهندس الجمل',type:'تحدّي الكتابة',match:'وصّل الكلمات',general:'السباق السريع'};
    startQuiz({mode:'practice',id:mode,title:labels[mode]||'تحدّي سريع',items:shuffled(pool).slice(0,Math.min(6,pool.length))});}
  function startQuiz({mode,id,title,items}){quiz={mode,id,title,items,index:0,correct:0,results:[],answered:false,feedback:null,hearts:5,orderIndices:[],matchSelected:-1,matchFound:[],matchErrors:0,matchOrder:[]};initQuizItem();page='quiz';result=null;render();}
  function initQuizItem(){if(!quiz||quiz.index>=quiz.items.length)return;quiz.answered=false;quiz.feedback=null;quiz.orderIndices=[];quiz.matchSelected=-1;quiz.matchFound=[];quiz.matchErrors=0;const q=quiz.items[quiz.index];quiz.matchOrder=q.type==='match'?shuffled(q.pairs.map((_,i)=>i)):[];}
  function displayAnswer(q){if(q.type==='match')return q.pairs.map(([a,b])=>`${a} = ${b}`).join(' | ');if(q.type==='blend')return q.answer;if(q.type==='order')return q.answer;if(q.type==='type')return q.answers[0];return q.a;}
  function commitAnswer(correct,selected=''){if(!quiz||quiz.answered)return;const q=quiz.items[quiz.index];quiz.answered=true;quiz.results.push({uid:q.uid,skill:q.skill,correct,item:q});if(correct){quiz.correct++;}else{quiz.hearts=Math.max(0,quiz.hearts-1);}quiz.feedback={correct,selected,solution:displayAnswer(q),explain:q.explain||''};render();}
  function quizChoice(i){const q=quiz?.items[quiz.index];if(!q||quiz.answered)return;commitAnswer(q.options[Number(i)]===q.a,q.options[Number(i)]);}
  function submitType(){const q=quiz?.items[quiz.index];if(!q||quiz.answered)return;const field=document.getElementById('type-answer');const input=field?.value||'';if(!norm(input)){toast('اكتب إجابتك أولًا.');return;}commitAnswer(q.answers.some(v=>norm(v)===norm(input)),input);}
  function selectOrder(i){if(!quiz||quiz.answered)return;if(quiz.orderIndices.includes(i))return;quiz.orderIndices.push(i);render();}
  function removeOrder(i){if(!quiz||quiz.answered)return;quiz.orderIndices.splice(i,1);render();}
  function submitOrder(){const q=quiz?.items[quiz.index];if(!q||quiz.answered)return;if(!quiz.orderIndices.length){toast('اختر الكلمات أولًا.');return;}const text=quiz.orderIndices.map(i=>q.words[i]).join(q.words.every(w=>w.length===1)?'':' ');commitAnswer(norm(text)===norm(q.answer),text);}
  function selectBlend(i){if(!quiz||quiz.answered||quiz.orderIndices.includes(i))return;quiz.orderIndices.push(i);render();}
  function submitBlend(){const q=quiz?.items[quiz.index];if(!q||quiz.answered||q.type!=='blend')return;if(quiz.orderIndices.length!==q.answer.length){toast('كوّن الكلمة من ثلاثة أحرف أولًا.');return;}const attempted=quiz.orderIndices.map(i=>q.tiles[i]).join('');commitAnswer(norm(attempted)===norm(q.answer),attempted);}
  function pickMatch(side,i){if(!quiz||quiz.answered)return;const q=quiz.items[quiz.index];i=Number(i);if(side==='left'){if(quiz.matchFound.includes(i))return;quiz.matchSelected=i;render();return;}if(quiz.matchSelected===-1){toast('اختر أولًا كلمة من العمود الأيمن.');return;}const rightId=quiz.matchOrder[i];if(quiz.matchFound.includes(rightId))return;if(rightId===quiz.matchSelected){quiz.matchFound.push(rightId);quiz.matchSelected=-1;if(quiz.matchFound.length===q.pairs.length){commitAnswer(quiz.matchErrors===0,'');return;}}else{quiz.matchErrors++;quiz.matchSelected=-1;toast('حاول مجددًا! هذا الربط غير صحيح.');}render();}
  function nextQuiz(){if(!quiz?.answered)return;quiz.index++;if(quiz.index>=quiz.items.length){completeQuiz();return;}initQuizItem();render();}
  function completeQuiz(){const qz=quiz;const percentage=pct(qz.correct,qz.items.length),passed=percentage>=80;profile.attempts++;touchActivity();let earned=qz.correct*15+(passed?35:0);profile.xp+=earned;
    for(const row of qz.results){addStats(row.skill,row.correct);reviewProgress(row,row.correct);if(!row.correct){if(!profile.mistakes.some(m=>m.uid===row.uid))profile.mistakes.push({uid:row.uid,item:row.item});}else{profile.mistakes=profile.mistakes.filter(m=>m.uid!==row.uid);}}
    profile.mistakes=profile.mistakes.slice(-65);profile.history.unshift({mode:qz.mode,id:qz.id,score:percentage,date:now(),passed});profile.history=profile.history.slice(0,55);
    let promoted=false;
    if(qz.mode==='story'&&passed)profile.stories[qz.id]={score:Math.max(profile.stories[qz.id]?.score||0,percentage),date:now()};
    if(qz.mode==='readingPattern'&&passed)profile.readingPatterns[qz.id]={score:Math.max(profile.readingPatterns[qz.id]?.score||0,percentage),date:now()};
    if(qz.mode==='phonics'&&passed)profile.phonics[qz.id]={score:Math.max(profile.phonics[qz.id]?.score||0,percentage),date:now()};
    if(qz.mode==='foundation'&&passed)profile.foundations[qz.id]={score:Math.max(profile.foundations[qz.id]?.score||0,percentage),date:now()};
    if(qz.mode==='lesson'&&passed)profile.completed[qz.id]=Math.max(profile.completed[qz.id]||0,percentage);
    if(qz.mode==='gate'&&passed){profile.gatePass[qz.id]=true;const current=idx(profile.stage),gateIndex=idx(qz.id);if(gateIndex===current && current<stages.length-1){profile.stage=stages[current+1].id;promoted=true;}}
    if(qz.mode==='practice')profile.practiceCount++;
    const d=dailyInfo();d.total+=qz.items.length;d.correct+=qz.correct;
    if(d.correct>=8&&!d.bonusClaimed){profile.xp+=40;earned+=40;d.bonusClaimed=true;}
    profile.daily=d;
    result={title:qz.title,mode:qz.mode,id:qz.id,score:percentage,correct:qz.correct,total:qz.items.length,passed,promoted,xp:earned};quiz=null;page='result';store();render();}
  function renderQuiz(){const q=quiz.items[quiz.index],n=quiz.index+1,answered=quiz.answered,feedback=quiz.feedback;const textPart=(q.type==='listen'||q.type==='blend')?`<button class="sound-btn" data-action="say" data-say="${E(q.say)}"><span class="sound-emoji">🔊</span> استمع مجددًا</button><div class="small muted" style="margin:-8px 0 18px">اضغط لسماع النطق الإنجليزي.</div>`:'';
    let controls='';if(q.type==='choice'||q.type==='listen')controls=`<div class="options">${q.options.map((o,i)=>`<button class="option ${answered?(o===q.a?'correct':o===feedback.selected?'incorrect':''):''}" data-action="quiz-answer" data-i="${i}" ${answered?'disabled':''}>${english(o)}</button>`).join('')}</div>`;
    if(q.type==='type')controls=`<form data-form="answer-type"><div class="q-entry"><input class="input" id="type-answer" placeholder="Type your answer here" aria-label="اكتب الإجابة" autocomplete="off" autocapitalize="off" spellcheck="false" ${answered?'disabled':''}><button class="btn btn-primary" type="submit" ${answered?'disabled':''}>تحقّق ✓</button></div></form><p class="small muted">💡 تلميح: ${E(q.hint)}</p>`;
    if(q.type==='blend'){
      const selected=quiz.orderIndices.map((j,pos)=>`<button class="blend-piece selected" data-action="order-remove" data-pos="${pos}" ${answered?'disabled':''}>${english(q.tiles[j])} ×</button>`).join('');
      controls=`<div class="blend-zone" aria-label="الكلمة التي ركبتها">${selected||'<span class="muted small">اضغط الحروف لتكوين الكلمة…</span>'}</div><div class="blend-bank">${q.tiles.map((letter,j)=>`<button class="blend-piece" data-action="blend-pick" data-i="${j}" ${answered||quiz.orderIndices.includes(j)?'disabled':''}>${english(letter)}</button>`).join('')}</div><p class="small muted">اسمع الكلمة كاملة، ثم رتب الأصوات المكتوبة من اليسار إلى اليمين.</p>${!answered?'<button class="btn btn-primary" data-action="blend-submit">تحقّق من الكلمة ✓</button>':''}`;
    }
    if(q.type==='order'){const selected=quiz.orderIndices.map((i,pos)=>`<button class="word-tile selected" data-action="order-remove" data-pos="${pos}" ${answered?'disabled':''}>${english(q.words[i])} ×</button>`).join('');controls=`<div class="answer-zone word-bank">${selected||'<span class="small muted" style="margin:auto">اضغط الكلمات بالترتيب الصحيح…</span>'}</div><div class="word-bank">${q.words.map((w,i)=>`<button class="word-tile" data-action="order-pick" data-i="${i}" ${quiz.orderIndices.includes(i)||answered?'disabled':''}>${english(w)}</button>`).join('')}</div>${!answered?'<button class="btn btn-primary" style="margin-top:21px" data-action="order-submit">تحقّق من الترتيب ✓</button>':''}`;}
    if(q.type==='match'){controls=`<p class="small muted">اختر كلمة إنجليزية من العمود الأيمن، ثم معناها أو مقابلها من العمود الأيسر.</p><div class="match-columns"><div class="match-col">${q.pairs.map(([en],i)=>`<button class="match-tile ${quiz.matchSelected===i?'selected':quiz.matchFound.includes(i)?'matched':''}" data-action="match-left" data-i="${i}" ${quiz.matchFound.includes(i)||answered?'disabled':''}>${english(en)} ${quiz.matchFound.includes(i)?'✓':''}</button>`).join('')}</div><div class="match-col">${quiz.matchOrder.map((id,i)=>`<button class="match-tile ${quiz.matchFound.includes(id)?'matched':''}" data-action="match-right" data-i="${i}" ${quiz.matchFound.includes(id)||answered?'disabled':''}>${E(q.pairs[id][1])} ${quiz.matchFound.includes(id)?'✓':''}</button>`).join('')}</div></div>`;}
    return `<div class="quiz-frame"><div class="quiz-head"><button class="btn btn-ghost btn-sm" data-action="quit-quiz">→ خروج</button><span class="quiz-counter">${E(quiz.title)} • ${n} / ${quiz.items.length}</span><span class="hearts" aria-label="القلوب المتبقية">${'❤️'.repeat(quiz.hearts)}${'🩶'.repeat(5-quiz.hearts)}</span></div>${progressBar(pct(quiz.index,quiz.items.length))}<section class="quiz-card" style="margin-top:17px"><p class="q-heading">${q.type==='blend'?'🧩 ركّب الكلمة':q.type==='listen'?'🎧 مهارة الاستماع':q.type==='match'?'🔗 التوصيل':q.type==='order'?'🧩 ترتيب الكلمات':q.type==='type'?'✍️ تحدّي الكتابة':'💡 اختر الإجابة الصحيحة'}</p><h2 class="q-text">${E(q.q)}</h2>${textPart}${controls}${answered?`<div class="feedback ${feedback.correct?'':'bad-feedback'}"><strong>${feedback.correct?'🎉 إجابة صحيحة!':'💪 محاولة جيدة، تعلّم من الإجابة'}</strong>${!feedback.correct?`<p>الإجابة الصحيحة: <strong>${E(feedback.solution)}</strong></p>`:''}${feedback.explain?`<p>${E(feedback.explain)}</p>`:''}</div>`:''}</section><div class="quiz-footer"><div class="small muted">${answered?'💡 الفهم أهم من الحفظ':'🌟 فكر بهدوء قبل اختيار الإجابة'}</div>${answered?`<button class="btn btn-primary" data-action="quiz-next">${quiz.index===quiz.items.length-1?'شاهد نتيجتك 🏆':'السؤال التالي ←'}</button>`:''}</div></div>`;}
  function renderResult(){const r=result,st=activeStage();return `<div class="result-card"><div class="result-emoji">${r.promoted?'🎊':r.passed?'🏆':'💪'}</div><span class="chip">${r.mode==='story'?'اختبار فهم القصة':r.mode==='readingPattern'?'اختبار القراءة المتقدمة':r.mode==='phonics'?'تحدّي دمج الأصوات':r.mode==='foundation'?'اختبار الحروف':r.mode==='lesson'?'نتيجة الدرس':r.mode==='gate'?'تحدّي الترقية':'نتيجة اللعبة'}</span><h2 class="result-title">${r.promoted?'فتحت مرحلة جديدة!':r.passed?'تحدٍّ رائع!':'اقتربت من الهدف!'}</h2><p class="result-summary">${E(r.title)}<br>أجبت بشكل صحيح عن <strong>${r.correct} من ${r.total}</strong> أسئلة.</p><div style="max-width:390px;margin:18px auto"><div class="flex between"><strong>نسبة الإتقان</strong><strong>${r.score}%</strong></div>${progressBar(r.score)}</div><div class="grid-2" style="margin:18px 0"><div class="tip">⭐ ربحت <strong>${r.xp} XP</strong></div><div class="tip">${r.passed?'✅ نجحت في التحدّي':'🎯 النجاح يبدأ من 80%'}</div></div>${r.promoted?`<div class="tip" style="margin-bottom:16px">🎊 أصبحت الآن في مستوى <strong>${E(st.id)} — ${E(st.name)}</strong>! تم فتح دروسك الجديدة.</div>`:''}${!r.passed&&r.mode!=='practice'?`<div class="tip" style="margin-bottom:16px">أعد التحدّي لتحصل على 80% على الأقل. راجع إجاباتك وجرّب التدريبات.</div>`:''}<div class="flex wrap" style="justify-content:center;margin-top:19px">${r.mode!=='practice'?`<button class="btn btn-outline" data-action="${r.mode==='story'?'story-quiz':r.mode==='readingPattern'?'pattern-quiz':r.mode==='phonics'?'phonics-quiz':r.mode==='foundation'?'foundation-quiz':r.mode==='lesson'?'start-lesson':'start-gate'}" data-id="${E(r.id)}">🔁 أعد التحدّي</button>`:''}${r.mode==='story'||r.mode==='readingPattern'?'<button class="btn btn-primary" data-action="open-adventure">تابع المغامرات 📖</button>':r.mode==='phonics'?'<button class="btn btn-primary" data-action="open-phonics">الوحدة التالية 🧩</button>':r.mode==='foundation'?'<button class="btn btn-primary" data-action="open-foundations">المجموعة التالية 🔤</button>':'<button class="btn btn-primary" data-action="go-path">تابع مساري 🗺️</button>'}<button class="btn btn-outline" data-action="nav" data-page="games">🎮 ساحة الألعاب</button></div></div>`;}
  function renderModal(){if(!modal)return'';let title='',message='',affirm='نعم',action='';if(modal.kind==='exit'){title='الخروج من التحدّي؟';message='لن تُحفظ إجابات هذا التحدّي الجزئي. يمكنك العودة لاحقًا.';affirm='الخروج الآن';action='confirm-exit';}else if(modal.kind==='reset'){title='إعادة تحديد المستوى؟';message='ستُمسح نقاط ودروس ونتائج هذا المتعلم ويبدأ اختبار جديد. بقية المتعلمين لن يتأثروا.';affirm='نعم، أعد الاختبار';action='confirm-reset';}return `<div class="overlay" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="dialog"><h3>${E(title)}</h3><p>${E(message)}</p><div class="flex wrap"><button class="btn btn-primary" data-action="${action}">${affirm}</button><button class="btn btn-outline" data-action="close-modal">إلغاء</button></div></div></div>`;}
  function render(){if(!profile){appEl.innerHTML=renderWelcome();return;}const screens={intro:renderIntro,placement:renderPlacement,placementResult:renderPlacementResult,lessonPreview:renderLessonPreview,home:renderHome,path:renderPath,games:renderGames,speak:renderSpeak,achievements:renderAchievements,settings:renderSettings,foundations:renderFoundations,foundationLesson:renderFoundationLesson,phonics:renderPhonics,phonicLesson:renderPhonicLesson,adventure:renderAdventure,readingStory:renderStory,dialogPlay:renderDialogue,readingPattern:renderPattern,result:renderResult,quiz:renderQuiz};const f=quiz?renderQuiz:placementSession?renderPlacement:screens[page]||renderHome;appEl.innerHTML=renderShell(f());}
  appEl.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const cmd=form.dataset.form;if(cmd==='create'){const name=String(new FormData(form).get('name')||'').trim().slice(0,30);if(name.length<2){toast('أدخل اسمًا من حرفين على الأقل.');return;}const p=safeProfile({id:'p-'+Date.now()+'-'+Math.floor(Math.random()*99999),name,createdAt:now()});data.profiles.push(p);store();activate(p);}else if(cmd==='answer-type')submitType();});
  appEl.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id,mode=b.dataset.mode,i=b.dataset.i;
    switch(action){case 'choose-profile':{const p=data.profiles.find(x=>x.id===id);if(p)activate(p);break;}
      case 'switch-profile':profile=null;quiz=null;placementSession=null;page='home';modal=null;render();break;
      case 'nav':nav(b.dataset.page);break;
      case 'start-placement':startPlacement();break;
      case 'placement-answer':answerPlacement(i);break;
      case 'go-path':page='path';result=null;render();break;
    case 'open-adventure':{if(quiz||placementSession){modal={kind:'exit',to:'adventure'};render();break;}if(b.dataset.tab)adventureTab=b.dataset.tab;page='adventure';result=null;render();break;}
    case 'adventure-tab':adventureTab=b.dataset.tab||'stories';render();break;
    case 'read-story':{const x=stories.find(x=>x.id===id);if(!x||!adventureOpen(stories,x,profile.stories)){toast('أكمل القصة السابقة أولًا.');break;}storyId=id;page='readingStory';render();break;}
    case 'toggle-translation':showTranslation=!showTranslation;render();break;
    case 'story-quiz':beginStoryQuiz(id);break;
    case 'start-dialog':startDialogue(id);break;
    case 'dialog-answer':answerDialogue(b.dataset.value);break;
    case 'dialog-next':nextDialogue();break;
    case 'open-pattern':{const x=patterns.find(x=>x.id===id);if(!x||!isAvailableStage(x.stage)||(x.stage==='A0'&&!phonicsFinished())){toast('تعلّم الأصوات أولًا.');break;}patternId=id;page='readingPattern';render();break;}
    case 'pattern-quiz':startPatternQuiz(id);break;
    case 'open-phonics':{if(quiz||placementSession){modal={kind:'exit',to:'phonics'};render();break;}page='phonics';phonicsPageId=null;result=null;render();break;}
    case 'open-phonic':{const g=phonics.find(x=>x.id===id);if(!g||!phonicsAvailable(g)){toast('أكمل الوحدة السابقة أولًا.');break;}phonicsPageId=id;page='phonicLesson';render();break;}
    case 'phonics-quiz':startPhonicsQuiz(id);break;
    case 'blend-pick':selectBlend(Number(i));break;
    case 'blend-submit':submitBlend();break;
    case 'open-foundations':{if(quiz||placementSession){modal={kind:'exit',to:'foundations'};render();break;}page='foundations';foundationPageId=null;result=null;render();break;}
    case 'open-foundation':{const g=foundations.find(g=>g.id===id);if(!g||!foundationGroupAvailable(g)){toast('أكمل المجموعة السابقة أولًا.');break;}foundationPageId=id;page='foundationLesson';render();break;}
    case 'foundation-quiz':startFoundationQuiz(id);break;
      case 'start-lesson':startLesson(id);break;
      case 'begin-lesson':beginLesson(id);break;
      case 'flip-card':{const j=Number(i);if(openedCards.has(j))openedCards.delete(j);else openedCards.add(j);render();break;}
      case 'start-gate':startGate(id);break;
      case 'practice':practice(mode);break;
      case 'quiz-answer':quizChoice(i);break;
      case 'quiz-next':nextQuiz();break;
      case 'order-pick':selectOrder(Number(i));break;
      case 'order-remove':removeOrder(Number(b.dataset.pos));break;
      case 'order-submit':submitOrder();break;
      case 'match-left':pickMatch('left',i);break;
      case 'match-right':pickMatch('right',i);break;
      case 'say':pronounce(b.dataset.say);break;
      case 'letter':{const row=alphabet.find(x=>x[0]===b.dataset.letter);if(row){pronounce(`${row[0]}. ${row[1]}`);toast(`${row[0]} • ${row[1]} • ${row[2]}`);}break;}
      case 'quit-quiz':modal={kind:'exit',to:'path'};render();break;
      case 'close-modal':modal=null;render();break;
      case 'confirm-exit':{const target=modal?.to||'path';quiz=null;placementSession=null;modal=null;page=target;render();break;}
      case 'ask-reset':modal={kind:'reset'};render();break;
      case 'confirm-reset':{const p=safeProfile({id:profile.id,name:profile.name,createdAt:now()});const pos=data.profiles.findIndex(x=>x.id===profile.id);data.profiles[pos]=p;store();activate(p);break;}
      case 'open-speak':page='speak';pronounceIndex=0;micStatus='';render();break;
      case 'speak-next':pronounceIndex++;micStatus='';render();break;
      case 'mic':startMic();break;
      case 'pick-import':document.getElementById('import-file')?.click();break;
      case 'export-progress':exportProgress();break;
    }
  });
  appEl.addEventListener('change',e=>{if(e.target?.id!=='import-file')return;const file=e.target.files?.[0];if(!file)return;
    if(file.size>1024*1024){toast('ملف التقدم أكبر من 1 ميغابايت؛ اختر ملف JSON الذي صدّرته من اللعبة.');return;}
    const reader=new FileReader();reader.onload=()=>{
      try{const raw=JSON.parse(String(reader.result||''));if(!raw||typeof raw!=='object'||Array.isArray(raw)||typeof raw.name!=='string'||!raw.id||!('placementDone' in raw))throw new Error('format');
        if(raw.stage&&!stages.some(s=>s.id===raw.stage))throw new Error('level');
        const p=safeProfile({...raw,id:'import-'+Date.now()+'-'+Math.floor(Math.random()*9999),name:raw.name.trim().slice(0,30)||'متعلم مستورد'});
        for(const m of p.mistakes){if(m?.uid&&m.item&&!p.reviewCards[m.uid])p.reviewCards[m.uid]={item:m.item,dueAt:0,step:0,lapses:1};}
        data.profiles.push(p);store();activate(p);toast('تم استيراد ملف التعلم. تأكد من صحة إنجازاتك ومسارك.');
      }catch{toast('تعذّر الاستيراد. اختر JSON مصدّرًا من مغامرة إنجليش V2 أو V3 أو V4.');}
    };reader.onerror=()=>toast('تعذّر قراءة الملف.');reader.readAsText(file,'UTF-8');
  });
  function startMic(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){micStatus='ميزة التعرف على الصوت غير متاحة في هذا المتصفح. استخدم زر الاستماع وكرّر الجملة بنفسك.';render();return;}const target=pronunciation[profile.stage][pronounceIndex%pronunciation[profile.stage].length];try{const rec=new Recognition();rec.lang='en-US';rec.interimResults=false;rec.maxAlternatives=1;micStatus='🎙️ تحدّث الآن بوضوح…';render();rec.onresult=evt=>{const heard=evt.results[0][0].transcript;const expected=norm(target).split(' '),got=norm(heard).split(' ');const matched=expected.filter(w=>got.includes(w)).length;const score=pct(matched,expected.length);micStatus=`سمع المتصفح: “${heard}” — تطابق الكلمات التقريبي ${score}%. ${score>=75?'ممتاز، واصل!':'حاول مرة أخرى وتحدّث ببطء.'} (هذا ليس تقييمًا صوتيًا متخصصًا)`;render();};rec.onerror=ev=>{micStatus='تعذّر استخدام الميكروفون ('+ev.error+'). يمكنك ممارسة النطق بالاستماع والتكرار.';render();};rec.start();}catch{micStatus='تعذّر بدء التعرف على الصوت. تحقق من إذن الميكروفون والمتصفح.';render();}}
  function exportProgress(){const blob=new Blob([JSON.stringify(profile,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='lingoquest-progress-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
  if('serviceWorker' in navigator && (location.protocol==='https:'||location.hostname==='localhost'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
  render();
})();
